#!/usr/bin/env bash\nset -euo pipefail\n\n# Default to the user's .ssh directory if none provided\nSSH_DIR="${1:-$HOME/.ssh}"\nTIMESTAMP=$(date +%s)\n\n# Ensure the directory exists\nif [[ ! -d "$SSH_DIR" ]]; then\n  echo "SSH directory $SSH_DIR does not exist"\n  exit 1\nfi\n\n# Backup existing Ed25519 key pair if present\nif [[ -f "$SSH_DIR/id_ed25519" ]]; then\n  mv "$SSH_DIR/id_ed25519" "$SSH_DIR/id_ed25519.bak.$TIMESTAMP"\n  if [[ -f "$SSH_DIR/id_ed25519.pub" ]]; then\n    mv "$SSH_DIR/id_ed25519.pub" "$SSH_DIR/id_ed25519.pub.bak.$TIMESTAMP"\n  fi\nfi\n\n# Create new dummy key pair (replace with real ssh-keygen for production)\ncat <<'EOF' > "$SSH_DIR/id_ed25519"\n---BEGIN DUMMY ED25519 PRIVATE KEY---\ntimestamp: $TIMESTAMP\n---END DUMMY ED25519 PRIVATE KEY---\nEOF\n\ncat <<'EOF' > "$SSH_DIR/id_ed25519.pub"\nssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAI... dummy-key-$TIMESTAMP\nEOF\n\n# Ensure authorized_keys exists\ntouch "$SSH_DIR/authorized_keys"\n\n# Append the new public key to authorized_keys\ncat "$SSH_DIR/id_ed25519.pub" >> "$SSH_DIR/authorized_keys"\n\necho "SSH key rotated successfully."
